@Test
public void toFormattedStringWithTimezone() {
    final FTPFile file = new FTPFile();
    file.setType(FTPFile.FILE_TYPE);
    file.setSize(32767);
    file.setUser("Apache");
    file.setGroup("Apache Group");
    file.setName("virus.bat");
    final Calendar timestamp = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
    timestamp.set(1969, Calendar.JULY, 16, 13, 32, 0);
    file.setTimestamp(timestamp);
    file.setPermission(FTPFile.USER_ACCESS, FTPFile.READ_PERMISSION, true);
    file.setPermission(FTPFile.USER_ACCESS, FTPFile.WRITE_PERMISSION, true);
    file.setPermission(FTPFile.USER_ACCESS, FTPFile.EXECUTE_PERMISSION, true);
    final String formattedString = file.toFormattedString("GMT");
    assertAll(() -> assertTrue(formattedString.startsWith("-")), () -> assertTrue(formattedString.startsWith("rwx", 1)), () -> assertTrue(formattedString.contains(file.getUser())), () -> assertTrue(formattedString.contains(file.getGroup())), () -> assertTrue(formattedString.contains(String.valueOf(file.getSize()))), () -> assertTrue(formattedString.contains("1969-07-16 13:32:00")), () -> assertTrue(formattedString.contains("GMT")), () -> assertTrue(formattedString.contains(file.getName())));
}

